// apps/api/src/lib/queue.ts
var pending = [];
var draining = false;
var drain = async () => {
  if (draining) return;
  draining = true;
  try {
    while (pending.length > 0) {
      const next = pending.shift();
      try {
        await next.job();
      } catch (error) {
        console.error("[queue] job %s threw: %s", next.name, error);
      }
    }
  } finally {
    draining = false;
  }
};
var enqueue = (name, job) => {
  pending.push({ name, job });
  void drain();
};

