// apps/api/src/services/extraction/fallback.ts
var FallbackExtractionProvider = class {
  constructor(primary, secondary) {
    this.primary = primary;
    this.secondary = secondary;
    this.name = `${primary.name}+${secondary.name}`;
  }
  primary;
  secondary;
  name;
  /** Healthy if either engine can answer. */
  async healthy() {
    return await this.primary.healthy() || await this.secondary.healthy();
  }
  extractSignature(input) {
    return this.run(input, (p) => p.extractSignature(input));
  }
  extractStamp(input) {
    return this.run(input, (p) => p.extractStamp(input));
  }
  async run(_input, call) {
    try {
      const result = await call(this.primary);
      return { ...result, meta: { ...result.meta, engine: this.primary.name, fellBack: false } };
    } catch (error) {
      if (!isServiceFailure(error)) throw error;
      console.warn(
        "[extraction] %s unavailable (%s) \u2014 falling back to %s",
        this.primary.name,
        error instanceof Error ? error.message : String(error),
        this.secondary.name
      );
      const result = await call(this.secondary);
      return {
        ...result,
        meta: {
          ...result.meta,
          engine: this.secondary.name,
          fellBack: true,
          fellBackFrom: this.primary.name,
          reason: error instanceof Error ? error.message : String(error)
        }
      };
    }
  }
};
var isServiceFailure = (error) => {
  if (!(error instanceof HttpError)) return true;
  return error.status !== 422;
};

// apps/api/src/services/extraction/index.ts
var singletons = /* @__PURE__ */ new Map();
var composed = /* @__PURE__ */ new Map();
var override = null;
var bare = (engine) => {
  let provider = singletons.get(engine);
  if (!provider) {
    provider = engine === "removebg" ? new RemoveBgProvider() : engine === "rembg" ? new RembgProvider() : new SignatureRemoveBgProvider();
    singletons.set(engine, provider);
  }
  return provider;
};
var createExtractionProvider = (engine = env.EXTRACTION_ENGINE) => {
  if (override) return override;
  if (!env.EXTRACTION_FALLBACK) return bare(engine);
  let provider = composed.get(engine);
  if (!provider) {
    const other = engine === "local" ? "rembg" : "local";
    provider = new FallbackExtractionProvider(bare(engine), bare(other));
    composed.set(engine, provider);
  }
  return provider;
};

