sessionRoutes.post("/signing-sessions/:id/regions", async (c) => {
  const user = c.get("user");
  const { data: session } = await db.from("signing_sessions").select("*").eq("id", c.req.param("id")).eq("owner_id", user.id).maybeSingle();
  if (!session) throw notFound("Session introuvable.");
  assertShareScope(c.get("share"), session.folder_id);
  if (session.status === "processing") return c.json(toModel2(session), 202);
  if (session.status === "completed") return c.json(toModel2(session));
  const parsed2 = submitRegionsSchema.safeParse(await c.req.json().catch(() => null));
  if (!parsed2.success) {
    throw badRequest("Zones s\xE9lectionn\xE9es invalides.", "BAD_REQUEST", parsed2.error.issues);
  }
  if (session.capture_mode === "per_mark") {
    const photoFor = {
      signature: session.signature_photo_path,
      stamp: session.stamp_photo_path,
      mention: session.mention_photo_path,
      signature_stamp: session.signature_stamp_photo_path
    };
    const missing = ZONE_TYPE.filter(
      (mark) => parsed2.data[mark] && !photoFor[mark]
    );
    if (missing.length > 0) {
      throw badRequest(
        `Photo manquante pour : ${missing.map((m) => ZONE_TYPE_LABEL[m].toLowerCase()).join(", ")}. Reprenez la capture depuis le d\xE9but.`,
        "IMAGE_PROCESSING_FAILED",
        { missing }
      );
    }
  }
  const { data: updated } = await db.from("signing_sessions").update({ status: "processing", error_code: null, error_message: null }).eq("id", session.id).select("*").single();
  const run = () => processSigningSession(session.id, {
    signature: parsed2.data.signature,
    stamp: parsed2.data.stamp ?? null,
    mention: parsed2.data.mention ?? null,
    signature_stamp: parsed2.data.signature_stamp ?? null,
    assignments: parsed2.data.assignments
  });
  if (env.PROCESS_INLINE) {
    await run();
  } else {
    enqueue(`session:${session.id}`, run);
  }
  await audit({
    ownerId: user.id,
    folderId: session.folder_id,
    action: "session.regions_submitted",
    metadata: {
      sessionId: session.id,
      captureMode: session.capture_mode,
      hasStamp: Boolean(parsed2.data.stamp),
      hasMention: Boolean(parsed2.data.mention),
      assigned: Object.keys(parsed2.data.assignments ?? {})
    }
  });
  return c.json(toModel2(updated), 202);
});
